// 主要做数据存储，存储商家组件收藏,根据商家不同id去存储不同数据
export function saveToLocal(id, key, value) {
    /*
    * localStorage 和 sessionStorage 属性允许在浏览器中存储 key/value 对的数据
    * localStorage 用于长久保存整个网站的数据，保存的数据没有过期时间，直到手动去删除。localStorage 属性是只读的。
    * localStorage要加上window.localStorage
    * */
    // localStorage专门用一个_seller_字段，将所有值存到localStorage._seller_下面
    let seller = window.localStorage._seller_;
    // seller如果为空
    if (!seller) {
        seller = {};
        seller[id] = {};
    } else {
        seller = JSON.parse(seller);
        if (!seller[id]) {
            seller[id] = {};
        }
    }
    seller[id][key] = value;
    window.localStorage._seller_ = JSON.stringify(seller);
}

// 读取
export function loadFromLocal(id, key, def) {
    let seller = window.localStorage._seller_;
    // 如果没有seller,就返回默认值
    if (!seller) {
        return def;
    }
    // 有_seller_,则转化json，然后取当前商家的对象，因为存的是JSON字符串，所以要转化成json对象,同时拿到对应的id
    seller = JSON.parse(seller)[id];
    // 如果取到的id为空
    if (!seller) {
        return def;
    }
    // 如果取到了就看商家下面有没有key，没有还是返回默认值，有就取出值
    let ret = seller[key];
    return ret || def;
}

