<template>
    <header class="header">
        <div class="content-wrapper" @click="toggleDetail">
            <div class="content">
                <div class="avatar">
                    <img :src="seller.avatar" width="65" height="65">
                </div>
                <div class="shopinfo">
                    <div class="title">
                        <cite class="icon-title"></cite>
                        <span>{{seller.name}}</span>
                    </div>
                    <div class="info">
                        <span>{{seller.description}}</span> /
                        <span>{{seller.deliveryTime}}分钟送达</span>
                    </div>
                    <!-- 因为seller会延迟渲染，开始接受的seller是空 所以要用v-if判断  -->
                    <div class="info bot" v-if="seller.supports">
                        <cite class="icon-info" :class="classMap[seller.supports[0].type]"></cite>
                        <span>{{seller.supports[0].description}}</span>
                        <span class="supports-all">
                            {{seller.supports.length}}个
                            <i class="icon-keyboard_arrow_right"></i>
                        </span>
                    </div>
                </div>
            </div>
            <div class="bulletin">
                <cite class="icon-tell"></cite>
                <span>{{seller.bulletin}}</span>
                <i class="icon-keyboard_arrow_right"></i>
            </div>
        </div>
        <div class="background">
            <img :src="seller.avatar" width="100%" height="100%">
        </div>
        <!--    弹窗   -->
        <transition name="fade">
            <section class="detail" v-show="detailShow">
                <div class="detail-wrapper clear-fix">
                    <div class="detail-main">
                        <div class="name">{{seller.name}}</div>
                        <div class="star-wrapper">
                            <star :size="48" :score="seller.score"></star>
                        </div>
                        <div class="title">
                            <span class="line"></span>
                            <p>优惠信息</p>
                            <span class="line"></span>
                        </div>
                        <!-- 因为开始未获取数据所以 supports是空要先判断一下  -->
                        <ul v-if="seller.supports" class="supports-list">
                            <li v-for="(item,index) in seller.supports" :key="index">
                                <cite class="detail-icon" :class="classMap[item.type]"></cite>
                                <span class="text">{{item.description}}</span>
                            </li>
                        </ul>
                        <div class="title">
                            <span class="line"></span>
                            <p>商家公告</p>
                            <span class="line"></span>
                        </div>
                        <p class="detail-bulletin">{{seller.bulletin}}</p>
                    </div>
                </div>
                <div class="detail-close" @click="toggleDetail">
                    <i class="icon-close"></i>
                </div>
            </section>
        </transition>
    </header>
</template>

<script type="text/ecmascript-6">
    import Star from 'components/star/star';
    export default {
        name: 'v-header',
        props: {
            seller: {
                type: Object
            }
        },
        data() {
          //  v-show与小程序hidden相反 v-show=false=隐藏 v-show=true显示,所以命名以xxxshow为好 小程序以xxxhide为好
          return {
              detailShow: false
          }
        },
        created() {
            // 只应用于本组件的变量可以不用在data中注册
            this.classMap = ['decrease', 'discount', 'special', 'invoice', 'guarantee'];
        },
        methods: {
            toggleDetail: function () {
                this.detailShow = !this.detailShow;
            }
        },
        components: {
            Star
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
    /* 所应用的字体css/style文件不能在组件中引用 这里在main.js中引用 */
    @import '../../common/stylus/mixin.styl';
    .header
        position: relative
        background-color rgba(7,17,27,.5)
        .background
            position: absolute
            top: 0
            left: 0
            width: 100%
            height: 100%
            z-index: -1
            filter: blur(10px)

        .content-wrapper
            overflow: hidden
            color: #fff

            .content
                box-sizing: border-box
                padding: 30px 20px 15px
                display: flex

                .avatar
                    width: 64px
                    height: 64px
                    overflow: hidden
                    border-radius: 5px

                .shopinfo
                    font-size: 14px
                    padding: 0px 0 0 10px
                    flex 1
                    position relative

                    .title
                        .icon-title
                            bg-image('brand')
                            width: 40px
                            height: 20px
                            display: inline-block
                            background-repeat: no-repeat
                            background-size: auto 20px

                        > span
                            font-size: 16px
                            display: inline-block
                            height: 20px
                            line-height: 20px
                            font-weight: bold
                            vertical-align: top

                    .info
                        font-size 12px
                        margin-top 5px

                        &.bot
                            margin-top 7px

                        > span
                            vertical-align top
                            display inline-block
                            height 14px
                            line-height 14px
                            font-size 12px

                        .icon-info
                            display: inline-block
                            width 20px
                            height 14px
                            background-repeat no-repeat
                            background-size auto 14px

                            &.decrease
                                bg-image('decrease_1')

                            &.discount
                                bg-image('discount_1')

                            &.guarantee
                                bg-image('guarantee_1')

                            &.invoice
                                bg-image('invoice_1')

                            &.special
                                bg-image('special_1')

                        .supports-all
                            display block
                            position absolute
                            right 0
                            bottom 0
                            background-color rgba(0, 0, 0, 0.3)
                            line-height 20px
                            height 20px
                            padding 2px 5px 2px 10px
                            border-radius 20px
                            font-size 10px

                            > i
                                display inline-block
                                font-size 12px
                                transform translate(0, 2px)

            .bulletin
                background: rgba(0, 0, 0, 0.3)
                height: 30px
                padding: 0 10px
                display: flex
                flex-wrap: nowrap
                align-items: center

                .icon-tell
                    display: inline-block
                    bg-image('bulletin')
                    width: 26px
                    height: 16px
                    background-size: auto 14px
                    background-repeat: no-repeat

                .icon-keyboard_arrow_right
                    margin-left: 0px
                    line-height: 24px
                    font-size: 14px

                span
                    display: inline-block
                    flex 1
                    vertical-align: top
                    height: 30px
                    font-size: 12px
                    line-height: 30px
                    overflow: hidden
                    white-space: nowrap
                    text-overflow: ellipsis
                    padding-left: 5px


        .detail
            position fixed
            left 0
            right 0
            top 0
            background: rgba(7,17,27,.8)
            backdrop-filter: blur(10px)
            width 100%
            height 100%
            z-index 300
            overflow auto
            /* 过度动画css https://cn.vuejs.org/v2/guide/transitions.html 是谁的动画就写在那个元素上 */
            &.fade-enter-active, &.fade-leave-active
                transition all 0.5s
            &.fade-enter, &.fade-leave-active
                opacity 0
                background: rgba(7,17,27,0)

            .detail-wrapper
                min-height 100%

                .detail-main
                    margin-top 64px
                    padding-bottom 64px

                    .name
                        width 100%
                        font-size 16px
                        font-weight 700
                        text-align center
                        color #fff
                    .star-wrapper
                        width 180px
                        margin 20px auto 0
                    .title
                        display flex
                        width 80%
                        margin 30px auto 25px
                        color #fff

                        .line
                            flex 1
                            position relative
                            top -6px
                            border-bottom 1px solid hsla(0, 0%, 100%, 0.2)

                        p
                            font-size 14px
                            font-weight 700
                            padding 0 20px

                    .supports-list
                        width 80%
                        margin 10px auto 0

                        > li
                            width 100%
                            color #fff
                            height 20px
                            padding 5px 0
                            font-size 14px
                            display flex

                            .detail-icon
                                display inline-block
                                width 30px
                                height 20px
                                background-repeat no-repeat
                                background-position left center
                                background-size auto 20px
                                &.decrease
                                    bg-image('decrease_2')
                                &.discount
                                    bg-image('discount_2')
                                &.guarantee
                                    bg-image('guarantee_2')
                                &.invoice
                                    bg-image('invoice_2')
                                &.special
                                    bg-image('special_2')
                            .text
                                display inline-block
                                height 20px
                                line-height 20px

                    .detail-bulletin
                        width 80%
                        margin 0 auto
                        font-size 14px
                        color #fff
                        line-height 24px
            .detail-close
                position relative
                width 32px
                height 32px
                margin -64px auto 0 auto
                clear both
                font-size 32px
                color #fff

</style>
