<template>
    <transition name="moveIn">
        <section class="food" v-show="foodShow" ref="food">
            <div class="food-container">
                    <div class="head-wrapper">
                        <div class="back" @click="closeFood">
                            <i class="icon-arrow_lift arrow"></i>
                        </div>
                        <img :src="food.image" class="head-img">
                    </div>
                    <div class="title-wrapper">
                        <h2 class="name">{{food.name}}</h2>
                        <div class="small">
                            <span>月售{{food.sellCount}}份</span>
                            <span>好评率{{food.rating}}%</span>
                        </div>
                        <div class="price" @click="addFood">
                    <span class="left">
                        <em class="now">￥{{food.price}}</em>
                        <em v-if="food.oldPrice" class="old">￥{{food.oldPrice}}</em>
                    </span>
                            <span class="right">
                        <!--  添加渐隐的效果，否则直接隐藏小球下落的时候会找不到点击的位置，
        下落球会从顶部下落,所以加一个缓动延迟,当渐隐的时候，元素的位置没有发生变化没有隐藏所以小球下落动画拿到的位置就是正确的    -->
                        <transition name="fadeOut">
                            <!-- 这里要阻止点击的默认事件以及向上冒泡，否则第一次点击加入购物车时会触发cartcontrol的点击事件，造成给good传递的target不正确的问题 -->
                            <em
                                    class="addtocart"
                                    v-show="!food.count || food.count === 0"
                                    @click.stop.prevent="addFirst"
                            >
                                加入购物车
                            </em>
                        </transition>
                        <div class="cartcontrol-wrapper" v-show="food.count">
                            <cartcontrol :food="food" @add="addFood"></cartcontrol>
                        </div>
                    </span>
                        </div>
                    </div>
                    <!--   title end  -->
                    <split v-show="food.info"></split>
                    <div class="info-wrapper" v-show="food.info">
                        <div class="title">商品信息</div>
                        <p class="text">{{food.info}}</p>
                    </div>
                    <split></split>
                    <div class="ratings-wrapper">
                        <div class="title">商品评价</div>
                        <div class="rating-box border-1px">
                            <rating-select
                                    :selectType="selectType"
                                    :desc="desc"
                                    :onlyContent="onlyContent"
                                    :ratings="food.ratings"
                                    @select="tabSelect"
                                    @toggle="toggle"
                            ></rating-select>
                        </div>
                        <div class="rating-content">
                            <ul v-show="computedRatings && computedRatings.length">
                                <li
                                        class="rating-item border-1px"
                                        v-for="(rating, index) in computedRatings"
                                        :key="index"
                                >
                                    <div class="top">
                                        <span class="time">{{format(rating.rateTime)}}</span>
                                        <span class="user">
                                            <em>{{rating.username}}</em>
                                            <img :src="rating.avatar" width="20" height="20">
                                        </span>
                                    </div>
                                    <div class="content">
                                        <!--    这里不能用三元表达式会出错   -->
                                        <i class="icon" :class="{'icon-thumb_up': rating.rateType === 0, 'icon-thumb_down': rating.rateType === 1}"></i>
                                        <p class="text">{{rating.text}}</p>
                                    </div>
                                </li>
                            </ul>
                            <!--  当没有评论或者评论其中之一为false时就隐藏，使用计算属性这个效果实现容易只要computedRatings中没数据就显示  -->
                            <div class="no-rating" v-show=" !computedRatings || !computedRatings.length">暂无评价</div>
                        </div>
                        <!--   rating-content end   -->
                    </div>
                    <!--   ratings-wrapper end   -->
                </div>
        </section>
    </transition>
</template>

<script type="text/ecmascript-6">
    import split from "../split/split";
    import cartcontrol from "../cartcontrol/cartcontrol";
    import ratingSelect from "../rating-select/rating-select";
    import Vue from 'vue';
    import BScroll from 'better-scroll'
    import moment from 'moment';

    const EVENT_FOODADD = 'foodadd';
    // 与后端约定数字代表差评好评等含义
    const ALL = 2;
    const POSITIVE = 0;
    const NEGATIVE = 1;

    export default {
        name: 'food',
        props: {
            food: {
                type: Object
            }
        },
        data() {
            return {
                foodShow: false,
                /* 定义rating-select需要的参数 */
                selectType: ALL,
                desc: {
                    all: '全部',
                    positive: '推荐',
                    negative: '差评'
                },
                onlyContent: false
            }
        },
        computed: {
            // 使用计算属性筛选择的商品，用计算属性实现比较好
            computedRatings: function () {
                let ret = [];
                if (this.food.ratings) {
                    // 遍历所有商品的评论
                    this.food.ratings.forEach((item) => {
                        // 根据选择的type进行筛选
                        switch (this.selectType) {
                            case ALL:
                                if (this.onlyContent) {
                                    if (item.text) {
                                        ret.push(item);
                                    }
                                } else {
                                    ret.push(item);
                                }
                                break;
                            case POSITIVE:
                                if (this.onlyContent) {
                                    // 当商品评价并且评价type与规定的好评相同时
                                    if (item.text && (item.rateType === POSITIVE)) {
                                        ret.push(item);
                                    }
                                } else {
                                    if (item.rateType === POSITIVE) {
                                        ret.push(item);
                                    }
                                }
                                break;
                            case NEGATIVE:
                                if (this.onlyContent) {
                                    if (item.text && item.rateType === NEGATIVE) {
                                        ret.push(item);
                                    }
                                } else {
                                    if (item.rateType === NEGATIVE) {
                                        ret.push(item);
                                    }
                                }
                        }
                    });
                }
                return ret;
            }
        },
        methods: {
            show: function () {
                this.foodShow = true;
                // 重置状态选择 显示的时候 3中状态都要重置
                this.selectType = ALL;
                this.onlyContent = false;
                this.noRatingShow = false;
                // BS的初始化要在show方法中执行不能在create中！会不滚动!这里切记，如果第一次进入food滚动而第二次进入不滚动，原因是foodScroll判断均要在$nextTick中进行！！！
                this.$nextTick(() => {
                    // 在show的时候 获取所有的Li,用于检查li display属性的计算，关于checkLiShow
                    let libox = document.querySelector('.rating-content');
                    this.lis = libox.querySelectorAll('li');

                    if (!this.foodScroll) {
                        // 必须要在bs中点击cartontrol才会才会被点击
                        this.foodScroll = new BScroll(this.$refs.food, {
                            click: true
                        });
                    } else {
                        // refresh也要在nextTick中执行！！！
                        this.foodScroll.refresh();
                    }
                });
            },
            closeFood: function (event) {
                // 在bs中event._constructed为true
                if (!event._constructed) {
                    return
                }
                this.foodShow = false;
            },
            // 第一次点击加入购物车时候的事件注意这里要阻止默认行为以及冒泡
            addFirst: function(event) {
                if (!event._constructed) {
                    return
                }
                if (!this.food.count) {
                    Vue.set(this.food, 'count', 1);
                    // 第一次点击的时候向外部传递添加事件good接收，并驱动小球下落动画，传递点击的目标，用来计算下落球的起点位置
                    this.$emit(EVENT_FOODADD, event.target)
                }
            },
            // 点击加号
            addFood: function (target) {
                // 向good组件发送事件驱动小球下落
                this.$emit(EVENT_FOODADD, target);
            },
            /* 点击好评选项卡 */
            tabSelect: function (type) {
                this.selectType = type;
                this.$nextTick(() => {
                   this.foodScroll.refresh();
                });
            },
            // 切换是否全显的状态
            toggle: function () {
                this.onlyContent = !this.onlyContent;
                this.$nextTick(() => {
                   this.foodScroll.refresh();
                });
            },
            // 格式化时间戳
            format(time) {
                return moment(time).format('YYYY-MM-DD hh:mm');
            }
        },
        components: {
            split,
            cartcontrol,
            'rating-select': ratingSelect
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
    @import '../../common/stylus/mixin.styl'
    $color-blue = rgb(0, 160, 220)
    .food
        position fixed
        z-index 90
        top 0
        bottom 50px
        left 0
        right 0
        width 100%
        height calc(100% - 50px)
        background-color #fff
        transform translate3d(0, 0, 0)
        overflow hidden
        &.moveIn-enter-active, &.moveIn-leave-active
            transition all 0.4s ease-in-out

        &.moveIn-enter, &.moveIn-leave-active
            transform translate3d(100%, 0, 0)

        .head-wrapper
            width 100%
            height 0
            padding-top 100%
            position relative
            .back
                position absolute
                left 15px
                top 20px
                background-color rgba(0,0,0, 0.5)
                border-radius 50%
                z-index 10
                width 30px
                height 30px
                line-height 30px
                display flex
                align-items center
                justify-content center
                .arrow
                    display inline-block
                    color #fff
            .head-img
                position absolute
                width 100%
                height 100%
                top 0%
                left 0%

        .title-wrapper
            padding 15px 15px 20px 15px

            .name
                font-size 18px
                font-weight 700
                padding-bottom 8px

            .small
                span
                    color #7e8c8d
                    font-size 14px
                    display inline-block

                    &:first-child
                        margin-right 10px

            .price
                position relative
                padding 20px 0 0 0
                display flex
                justify-content space-between

                .left
                    flex 1
                    height 30px
                    line-height 30px
                    display block
                    em
                        font-style normal
                        display inline-block
                        vertical-align top
                        &.now
                            color #f01414
                            font-size 16px
                            font-weight 700
                            margin-right 10px
                        &.old
                            color #7e8c8d
                            font-size 12px
                            text-decoration line-through
                .right
                    flex 0 0 100px
                    height 30px
                    display block
                    position relative
                    .addtocart
                        display block
                        position absolute
                        top 0
                        left 0
                        width 100%
                        height 30px
                        line-height 30px
                        font-size 14px
                        font-style normal
                        border-radius 20px
                        text-align center
                        background-color $color-blue
                        color #fff
                        opacity 1
                        &.fadeOut-enter-active, &.fadeOut-leave-active
                            transition all 0.4s ease-in-out
                        &.fadeOut-enter, &.fadeOut-leave-active
                            opacity 0
        .info-wrapper
            padding 15px
            .title
                padding-bottom 16px
                font-size 16px
            .text
                font-size 14px
                line-height 22px
                color #3d3d3d
        .ratings-wrapper
            .title
                font-size 16px
                padding 15px 15px 20px 15px
            .rating-box
                padding 0 15px
                border-1px(#666)
            .rating-content
                padding 0 15px 20px
                .rating-item
                    padding 15px 0
                    border-1px(#ccc)
                    .top
                        font-size 12px
                        color #7e8c8d
                        display flex
                        justify-content space-between
                        .time
                            display inline-block
                            height 20px
                            line-height 20px
                        .user
                            height 20px
                            line-height 20px
                            em
                                display inline-block
                                height 20px
                                line-height 20px
                                vertical-align top
                                font-style normal
                                margin-right 10px
                            img
                                border-radius 50%
                                display inline-block


                    .content
                        padding 10px 0 0px 26px
                        position relative
                        .icon
                            display inline-block
                            font-size 16px
                            position absolute
                            top 10px
                            left 0
                            &.icon-thumb_up
                                color #00a0dc
                            &.icon-thumb_down
                                color #7e8c8d
                        .text
                            color #333
                            font-size 14px
                            line-height 20px
                            display inline-block


                .no-rating
                    color #7e8c8d
                    font-size 14px
                    padding-top 10px
</style>
