<template>
    <div class="cart-control">
        <transition name="move">
            <span class="cart-decrease" v-show="food.count > 0" @click.stop.prevent="decreaseCart">
                 <i class="inner icon-remove_circle_outline"></i>
            </span>
        </transition>
        <span class="cart-count" v-show="food.count">{{food.count}}</span>
        <span class="cart-add" @click.stop.prevent="addCart">
            <i class="icon-add_circle"></i>
        </span>
    </div>
</template>

<script type="text/ecmascript-6">
    import Vue from 'vue';
    const EVENT_ADD = 'add';
    export default {
        name: 'cartcontrol',
        props: {
            food: {
                type: Object
            }
        },
        methods: {
            addCart: function (event) {
                // 注意在使用这个组件的时候必须要在bs中使用，否则点击会直接return
                if (!event._constructed) {
                    return
                }
                if (!this.food.count) {
                    Vue.set(this.food, 'count', 1)
                } else {
                    this.food.count++
                }
                // 向父组件发送事件
                this.$emit(EVENT_ADD, event.target)
            },
            decreaseCart: function (event) {
                if (!event._constructed) {
                    return
                }
                if (this.food.count) {
                    this.food.count--
                }
            }
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
.cart-control
    display: flex;
    justify-content: center;
    align-items: center;
    span
        display inline-block
        color #00a0dc
        font-size 24px
        vertical-align top
        padding 6px
    .cart-decrease
        opacity 1
        transform translate3d(0, 0, 0)
        .inner
            display inline-block /* 注意必须要加 */
            transform rotate(0)
            transition all 0.5s linear
        &.move-enter-active, &.move-leave-active
            transition all 0.5s linear
        &.move-enter, &.move-leave-active
            opacity 0
            transform translate3d(24px, 0, 0)
            .inner
                transform rotate(180deg)
    .cart-count
        color #93999f
        line-height 24px
        font-size 12px
        text-align center
        padding 6px 0
</style>
