<template>
    <div class="ratings" ref="ratings">
        <div class="ratings-container">
            <section class="points-wrapper">
                <div class="left">
                    <span class="point">{{seller.score}}</span>
                    <p class="point-title">综合评分</p>
                    <p class="point-desc">高于周边商家{{seller.rankRate}}%</p>
                </div>
                <div class="right">
                    <ul class="point-detail">
                        <li>
                            <div class="title">服务态度</div>
                            <div class="star-wrapper">
                                <star :size="36" :score="seller.serviceScore"></star>
                            </div>
                            <p class="point">{{seller.serviceScore}}</p>
                        </li>
                        <li>
                            <div class="title">商品评分</div>
                            <div class="star-wrapper">
                                <star :size="36" :score="seller.foodScore"></star>
                            </div>
                            <p class="point">{{seller.foodScore}}</p>
                        </li>
                        <li>
                            <div class="title">送达时间</div>
                            <div class="time">{{seller.deliveryTime}}分钟</div>
                        </li>
                    </ul>
                </div>
            </section>
            <split></split>
            <section class="ratings-wrapper">
                <div class="rating-box border-1px">
                    <rating-select
                            :desc="desc"
                            :onlyContent="onlyContent"
                            :selectType="selectType"
                            :ratings="ratings"
                            @select="tabSelect"
                            @toggle="toggle"
                    ></rating-select>
                </div>
                <div class="rating-content">
                    <ul class="rating-list" v-if="computedRatings || computedRatings.length">
                        <li v-for="(rating, index) in computedRatings" :key="index" class="rating-item border-1px">
                            <div class="avatar">
                                <img :src="rating.avatar" width="30" height="30">
                            </div>
                            <div class="content">
                                <span class="time">{{format(rating.rateTime)}}</span>
                                <span class="name">{{rating.username}}</span>
                                <div class="score">
                                    <div class="star-wrapper">
                                        <star :size="24" :score="rating.score"></star>
                                    </div>
                                    <em class="deliveryTime">{{rating.deliveryTime}}</em>
                                </div>
                                <p class="text">{{rating.text}}</p>
                                <div class="recommend" v-if="rating.recommend && rating.recommend.length">
                                    <i  :class="{'icon-thumb_up': rating.rateType === 0,'icon-thumb_down': rating.rateType === 1}"></i>
                                    <em
                                            class="recommend-item"
                                            v-for="(item, index) in rating.recommend"
                                            :key="index"
                                    >
                                        {{item}}
                                    </em>
                                </div>
                            </div>
                        </li>
                    </ul>
                </div>
            </section>
        </div>
    </div>
</template>

<script>
    import star from "../star/star";
    import split from "../split/split";
    import ratingSelect from '../rating-select/rating-select'
    import BScroll from 'better-scroll';
    import moment from 'moment';

    const ERR_OK = 0;
    const ALL = 2;
    const POSITIVE = 0;
    const NEGATIVE = 1;
    const debug = process.env.NODE_ENV !== 'production';
    export default {
        name: 'ratings',
        props: {
            seller: {
                type: Object
            }
        },
        data() {
            return {
                ratings: [],
                //  定义rating-select传递数据
                desc: {
                    all: '全部',
                    positive: '满意',
                    negative: '不满意'
                },
                onlyContent: false,
                selectType: ALL
            }
        },
        created() {
            const url = debug ? '/api/ratings' : 'http://634174214.gitee.io/myself-vue-elme/ratings.json';
            if (this.ratings.length <= 0) {
                this.$http.get(url).then((response) => {
                    response = response.body;
                    if (response.errno === ERR_OK) {
                        this.ratings = response.data;
                    }
                    // console.log(this.ratings);
                });
            }
            this.$nextTick(() => {
                this.ratingsScroll = new BScroll(this.$refs.ratings, {
                    click: true
                })
            });
        },
        computed: {
            computedRatings: function () {
                let ret = [];
                this.ratings.forEach((rating) => {
                    switch (this.selectType) {
                        case ALL:
                            if (this.onlyContent) {
                                if (rating.text) {
                                    ret.push(rating);
                                }
                            } else {
                                ret.push(rating);
                            }
                            break;
                        case POSITIVE:
                            if (this.onlyContent) {
                                if (rating.text && rating.rateType === POSITIVE) {
                                    ret.push(rating);
                                }
                            } else {
                                if (rating.rateType === POSITIVE) {
                                    ret.push(rating);
                                }
                            }
                            break;
                        case NEGATIVE:
                            if (this.onlyContent) {
                                if (rating.text && rating.rateType === NEGATIVE) {
                                    ret.push(rating);
                                }
                            } else {
                                if (rating.rateType === NEGATIVE) {
                                    ret.push(rating);
                                }
                            }
                            break;
                    }
                });
                return ret;
            }
        },
        methods: {
            tabSelect: function (type) {
                this.selectType = type;
                this.$nextTick(() => {
                   this.ratingsScroll.refresh();
                });
            },
            toggle: function () {
                this.onlyContent = !this.onlyContent;
                this.$nextTick(() => {
                    this.ratingsScroll.refresh();
                });
            },
            format: function (time) {
                return moment(time).format('YYYY-MM-DD hh:mm');
            }
        },
        components: {
            split,
            star,
            'rating-select': ratingSelect
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
    @import "../../common/stylus/mixin.styl"
    .ratings
        position absolute
        top 179px
        bottom 0
        left 0
        right 0
        overflow hidden
        .points-wrapper
            display flex
            padding 20px 0px 20px 0

            .left
                padding 5px 20px 0
                text-align center
                border-right 1px solid #ccc

                .point
                    color #fc9153
                    display block
                    width 100%
                    font-size 20px
                    padding 5px 0
                    font-weight 700

                .point-title
                    font-size 14px
                    padding 3px 0

                .point-desc
                    color #7e8c8d
                    padding 3px 0
                    font-size 12px

            .right
                padding 0 20px
                font-size 14px

                .point-detail
                    li
                        padding 3px 0
                        color #4d4d4d
                        display flex

                    .title
                        display inline-block
                        flex 0 0 70px
                        height 20px
                        line-height 20px

                    .star-wrapper
                        display inline-block
                        height 20px
                        flex 0 0 100px
                        /* 修改组件中局部修改第三方组件的样式，使用>>>穿透，针对style上有scoped属性情况 */

                        >>> .star-item
                            margin-right 0

                    .point
                        display inline-block
                        height 20px
                        line-height 20px
                        color #fc9153

                    .time
                        display inline-block
                        color #7e8c8d
                        height 20px
                        line-height 20px
                        vertical-align top


        .ratings-wrapper
            padding 0px
            .rating-box
                padding 15px 15px 0 15px
                border-1px(#ccc)
            .rating-content
                .rating-list
                    padding 0 15px
                    .rating-item
                        padding 15px 0
                        border-1px(#ddd)
                        display flex
                        .avatar
                            overflow hidden
                            flex 0 0 40px
                            img
                                border-radius 50%

                        .content
                            position relative
                            flex 1
                            .time
                                position absolute
                                right 0
                                top 0
                                font-size 12px
                                color #7e8c8d
                            .name
                                display block
                                font-size 10px
                                padding-bottom 5px
                            .score
                                .star-wrapper
                                    display inline-block
                                    >>> .star-item
                                        margin-right 5px
                                .deliveryTime
                                    display inline-block
                                    font-style normal
                                    font-size 12px
                                    color #7e8c8d
                                    padding-left 5px
                                    height 12px
                                    line-height 12px
                            .text
                                font-size 14px
                                padding 8px 0 10px
                                line-height 22px
                            .recommend
                                display flex
                                flex-wrap wrap
                                .icon-thumb_up
                                    display inline-block
                                    color #2196f3
                                    line-height 24px
                                    margin-right 10px
                                .recommend-item
                                    color #999
                                    display inline-block
                                    height 24px
                                    line-height 24px
                                    padding 0px 5px
                                    border 1px solid #ccc
                                    font-size 11px
                                    margin 0 5px 8px 0
                                    font-style normal
</style>
