import Vue from 'vue';
import Router from 'vue-router';
import goods from "../components/goods/goods";
import ratings from "../components/ratings/ratings";
import seller from "../components/seller/seller";
// https://jsfiddle.net/yyx990803/xgrjzsup/ 在app.vue中应用  https://router.vuejs.org/zh/api/#router-view
Vue.use(Router);

const routes = [
    {
        path: '/',
        redirect: '/goods'
    },
    {
        path: '/goods',
        component: goods
    },
    {
        path: '/ratings',
        component: ratings
    },
    {
        path: '/seller',
        component: seller
    }
];
// 配置点击的样式 https://router.vuejs.org/zh/api/#append
export default new Router({
    linkActiveClass: 'active',
    routes
})
