<template>
    <div class="seller" ref="seller">
        <section class="seller-container">
            <div class="shop-wrapper">
                <div class="favorite" :class="{'active': favorite}" @click="favoriteToggle">
                    <i class="icon-favorite"></i>
                    <em>{{favorite ? '已收藏' : '收藏'}}</em>
                </div>
                <h2 class="shop-name">{{seller.name}}</h2>
                <div class="shop-rating border-1px">
                    <div class="star-wrapper">
                        <star :size="36" :score="seller.score"></star>
                    </div>
                    <span class="count">({{seller.ratingCount}})</span>
                    <span class="count">月售{{seller.sellCount}}单</span>
                </div>
                <ul class="shop-mes">
                    <li class="mes-item">
                        <span class="title">起送价</span>
                        <p class="text">{{seller.minPrice}}<em>元</em></p>
                    </li>
                    <li class="mes-item">
                        <span class="title">商家配送</span>
                        <p class="text">{{seller.deliveryPrice}}<em>元</em></p>
                    </li>
                    <li class="mes-item">
                        <span class="title">平均配送时间</span>
                        <p class="text">{{seller.deliveryTime}}<em>分钟</em></p>
                    </li>
                </ul>
            </div>
            <split></split>
            <div class="bulletin-wrapper">
                <div class="title">公告与活动</div>
                <p class="text border-1px">{{seller.bulletin}}</p>
                <ul class="support-list" v-if="seller.supports && seller.supports.length">
                    <li class="support-item border-1px" v-for="(support, index) in seller.supports" :key="index">
                        <cite class="icon" :class="supportClsMap[index]"></cite>
                        <span class="desc">{{support.description}}</span>
                    </li>
                </ul>
            </div>
            <split></split>
            <div class="pic-wrapper">
                <div class="title">商家实景</div>
                <div class="pic-container" ref="pic">
                    <ul v-if="pics && pics.length" ref="picList">
                        <li class="pic-item"
                            v-for="(pic, index) in seller.pics"
                            :key="index"
                            @click="openImgAlert(index, $event)"
                        >
                            <img :src="pic">
                        </li>
                    </ul>
                </div>
            </div>
            <split></split>
            <div class="info-wrapper">
                <div class="title border-1px">商家信息</div>
                <ul class="info-list">
                    <li v-for="(info, index) in seller.infos" :key="index" class="info-item border-1px">
                        {{info}}
                    </li>
                </ul>
            </div>
        </section>
        <img-alert ref="imgAlert" :pics="pics"></img-alert>
    </div>
</template>

<script>
    import star from '../star/star';
    import split from '../split/split';
    import imgAlert from '../img-alert/img-alert';
    import BScroll from 'better-scroll';
    // 读取储存离线缓存的对象
    import { saveToLocal, loadFromLocal } from "../../common/js/storage";
    /*
    * 这里注意这个组件有个问题，就是当在http://localhost:8080/#/seller上刷新时候，created是打印不出this.seller数据的，
    * 这时做个测试在app.vue的created中，获取之后打印seller数据，之后在#/seller上刷新，发现app.vue中打印的数据在seller组件报错之后
    * 观察app组件，其中seller数据通过vue-router传递到各个组件的，所以得出结论，#/seller上刷新时，app.vue获取数据有延迟，会先执行seller组件中的语句，再去执行app中的语句
    * 从而造成报错解决方法1：进入的时候首先在商品页good，这样等点击到sell组件时候,seller数据页已经通过路由传递过来了，就是不能让评论、商品组件作为第一页
    * 解决2：这里再使用watch监听seller(watch中的seller就是props中的seller),当seller值变化时，再去执行滚动以及给ul进行宽度赋值
    * */
    export default {
        name: 'seller',
        props: {
            seller: {
                type: Object
            }
        },
        data() {
          return {
              favorite: (() => {
                 // 这里必须用es6语法箭头函数，否则报错
                 return loadFromLocal(this.seller.id, 'favorite', false);
              })()
          }
        },
        created() {
          this.supportClsMap = ['jian', 'zhe', 'te', 'piao', 'bao'];
        },
        computed: {
          pics: function () {
              return this.seller.pics;
          }
        },
        watch: {
            // 重点！要监听app.vue传递来的seller，监听到了再执行,去掉则会获取不到路由传递来的seller值
            seller: function () {
                // 在app.vue中设定在这里就可以监听到
                // console.log(this.seller.id)
                this.$nextTick(() => {
                    this._initScroll();
                    this._initPicScroll();
                });
            }
        },
        mounted() {
          //  BS初始化在mounted中初始化
          this.$nextTick(() => {
              // 将滚动单独封装成方法，根据需求，这里需要多次调用初始化所以进行封装
              this._initScroll();
              this._initPicScroll();
          });
        },
        methods: {
            favoriteToggle: function (event) {
                if (!event._constructed) {
                    return
                }
                this.favorite = !this.favorite;
                saveToLocal(this.seller.id, 'favorite', this.favorite);
            },
            openImgAlert: function (index, event) {
                if (!event._constructed) {
                    return
                }
                /* 获取点击的时候的位置,用于模拟微信图片向上显示效果，暂搁置 未实现
                let targetY = event.target.getBoundingClientRect();
                */
                // 点击的时候横向滚动到点击的元素，滚动持续300ms
                this.picScroll.scrollToElement(event.target, 300);
                this.$refs.imgAlert.show(index);
            },
            _initScroll: function () {
                if (!this.sellerScroll) {
                    this.sellerScroll = new BScroll(this.$refs.seller, {
                        click: true
                    });
                } else {
                    this.sellerScroll.refresh();
                }
            },
            _initPicScroll: function () {
                // 这里要先判断是否获取到了pic图片否则报错，因为这里当在#/seller刷新的时候，首先不会取得seller的值，这里要判断一下避免报错，当watch到值之后，会执行这里的方法
                if (this.seller.pics) {
                    // 这里必须要计算出横向ul的长度，否则不能滚动，配合样式white-space: nowrap,这里必须要计算，保证内层宽度>外层
                    let liwidth = 150;
                    let limargin = 6;
                    // 计算出ul的宽度，最后-limargin因为最后多了一个margin
                    let ulwidth = (liwidth + limargin) * this.seller.pics.length - limargin;
                    this.$refs.picList.style.width = ulwidth + 'px';
                    this.$nextTick(() => {
                        if (!this.picScroll) {
                            this.picScroll = new BScroll(this.$refs.pic,{
                                click: true,
                                scrollX: true,
                                // 横向滚动时 向依然保持滚动，eventPassthrough: 'vertical'
                                // 纵向滚动时，保留横向的原生滚动 eventPassthrough: 'horizontal'
                                eventPassthrough: 'vertical'
                            });
                        } else {
                            this.picScroll.refresh();
                        }
                    });
                }
            }
        },
        components: {
            star,
            split,
            'img-alert': imgAlert
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
    @import '../../common/stylus/mixin.styl';
    .seller
        position absolute
        top 179px
        left 0
        right 0
        bottom 0
        overflow hidden
        .shop-wrapper
            padding 15px
            position relative
            .favorite
                position absolute
                right 15px
                top 15px
                text-align center
                z-index 10
                &.active
                    .icon-favorite
                        color #f01414
                    em
                        color #4d4d4d
                .icon-favorite
                    font-size 24px
                    color #ccc
                em
                    font-style normal
                    font-size 10px
                    width 30px
                    color #777
                    text-align center
                    margin-top 5px
                    display block
            .shop-name
                font-size 16px

            .shop-rating
                display flex
                align-items center
                height 36px
                padding-bottom 10px
                border-1px(#ddd)
                .count
                    display inline-block
                    margin-left 10px
                    color #4d4d4d
                    font-size 12px

                .star-wrapper
                    display inline-block

                    >>> .star-item
                        margin-right 5px
            .shop-mes
                width 90vw
                margin 20px auto 0
                display flex
                .mes-item
                    flex 1
                    text-align center
                    border-right 1px solid #ccc
                    &:last-child
                        border-right 0
                    .title
                        color #7e8c8d
                        font-size 12px
                        display block
                        margin-bottom 7px
                    .text
                        font-size 24px
                        color #4d4d4d
                        em
                            font-style normal
                            font-size 10px


        .bulletin-wrapper
            padding 15px
            .text
                color #f01414
                padding 10px 10px 20px
                line-height 22px
                font-size 14px
                border-1px(#ccc)
            .support-list
                .support-item
                    font-size 14px
                    padding 20px 34px
                    position relative
                    border-1px(#f2f2f2)
                    &:last-child
                        border-none()
                    .icon
                        display block
                        width 16px
                        height 16px
                        position absolute
                        background-size auto 16px
                        background-position center center
                        left 10px
                        top 21px
                        &.jian
                            bg-image('decrease_4')
                        &.zhe
                            bg-image('discount_4')
                        &.bao
                            bg-image('guarantee_4')
                        &.piao
                            bg-image('invoice_4')
                        &.te
                            bg-image('special_4')

                    .desc
                        line-height 18px
                        display inline-block

        .pic-wrapper
            padding 15px
            .title
                padding-bottom 15px
                font-size 16px
            .pic-container
                width 100%
                overflow hidden
                /* 对于不换行有重要作用 */
                white-space: nowrap
                ul
                    height 110px
                .pic-item
                    display inline-block
                    margin-right 6px
                    height 110px
                    width 150px
                    img
                        width 100%
        .info-wrapper
            padding 15px
            .title
                font-size 16px
                padding-bottom 15px
                border-1px(#ccc)
            .info-list
                padding-bottom 10px
                .info-item
                    font-size 14px
                    padding 15px 15px 15px 15px
                    line-height 22px
                    border-1px(#f2f2f2)

</style>
