<template>
    <transition name="fadeIn">
        <div class="img-alert" v-show="alertShow" @click="_close">
            <div class="slide-wrapper">
                <span class="goprev btn" :class="{'arrow-fadeOut': first}" @click.stop.prevent="pagePrev">
                    <i class="icon-arrow_lift"></i>
                </span>
                <span class="gonext btn" :class="{'arrow-fadeOut': last}" @click.stop.prevent="pageNext">
                    <i class="icon-arrow_lift"></i>
                </span>
                <p class="nowpage">
                    <em class="now">{{nowpage}}</em> / {{pics.length}}
                </p>
                <div class="bigbox" ref="bigbox">
                    <ul class="biglist" v-if="pics && pics.length" ref="biglist">
                        <li
                                v-for="(pic, index) in pics"
                                :key="index"
                                class="big-item big-item-hook"
                                :style="`width:${screenWidth}px`"
                        >
                            <img :src="pic" class="bigImg">
                        </li>
                    </ul>
                </div>
            </div>
            <div class="close">
                <i class="icon-close"></i>
            </div>
        </div>
    </transition>
</template>

<script type="text/ecmascript-6">
    import BScroll from 'better-scroll';

    export default {
        name: 'img-alert',
        props: {
            pics: {
                type: Array,
                default() {
                    return [];
                }
            }
        },
        data() {
            return {
                alertShow: false,
                nowpage: 1,
                last: false,
                first: false
            }
        },
        created() {
            this.screenWidth = window.innerWidth;
        },
        // 如果在做组件调试时，应使用watch检测数据是否获取到，在获取到后再执行操作
        methods: {
            show: function (index) {
                // 在show的阶段初始化轮播滚动
                this.alertShow = true;
                if (this.pics.length > 0) {
                    this._initUlWidth();
                    this._initArrow(index);
                    this.$nextTick(() => {
                        if (!this.slideScroll) {
                            this.slideScroll = new BScroll(this.$refs.bigbox, {
                                scrollX: true,
                                scrollY: false,
                                momentum: false, // 惯性
                                snap: {
                                    loop: false, // 循环,此配置项暂有Bug
                                    threshold: 0.3,
                                    speed: 400 // 轮播间隔
                                },
                            });
                        } else {
                            this.slideScroll.refresh();
                        }
                        // goToPage(x 横轴的页数, y 横轴的页数, time, easing)
                        // 滚动动画设置为0 打开直接显示 否则会有个滚动到的时间
                        this.slideScroll.goToPage(index, 0, 0);
                        // 点击时候更改传递的图片当前页
                        this.nowpage = index + 1;
                        // 监听滚动结束更新页标
                        this._listenScrollEnd();
                    });
                }
            },
            // 监听滚动结束更新当前index
            _listenScrollEnd: function () {
                let _self = this;
                _self.slideScroll.on('scrollEnd', function () {
                    // 这里this指代slideScroll实例, this.getCurrentPage().pageX只以0为基准的当前页
                    let now = this.getCurrentPage().pageX;
                    switch (now) {
                        case 0:
                            _self.first = true;
                            break;
                        case _self.pics.length - 1:
                            _self.last = true;
                            break;
                        default:
                            _self.first = _self.last = false;
                    }
                    console.log(now)
                    _self.nowpage = now + 1;
                })
            },
            pagePrev: function () {
                this.slideScroll.prev();
            },
            pageNext: function () {
                this.slideScroll.next();
            },
            _close: function (event) {
                if (!event._constructed) {
                    return
                }
                this.alertShow = false;
            },
            // 初始化轮播横向宽度
            _initUlWidth: function () {
                let width = this.$refs.bigbox.clientWidth;
                let listWidth = width * this.pics.length;
                this.$refs.biglist.style.width = listWidth + 'px';
            },
            // 初始化箭头判断问题
            _initArrow: function (index) {
                switch (index) {
                    case 0:
                        this.first = true;
                        this.last = false;
                        break;
                    case this.pics.length - 1:
                        this.first = false;
                        this.last = true;
                        break;
                    default:
                        this.first = false;
                        this.last = false;
                }
            }
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
    @import '../../common/stylus/variable.styl'
    .img-alert
        position fixed
        width 100%
        height 100%
        top 0
        bottom 0
        left 0
        z-index 90
        opacity 1
        background-color $color-background-s

        &.fadeIn-enter-active, &.fadeIn-leave-active
            transition all 0.3s linear

            .bigbox
                transition all 0.2s linear

        &.fadeIn-enter, &.fadeIn-leave-active
            opacity 0

            .bigbox
                transform scale(0.8)

        .slide-wrapper
            width 100%
            overflow hidden
            position absolute
            top 50%
            transform translate3d(0, -50%, 0)

            .btn
                display block
                position absolute
                top 50%
                color #fff
                height 40px
                z-index 92
                margin-top -20px
                transition all 0.3s

                &.arrow-fadeOut
                    opacity 0

                &.goprev
                    left 10px
                    .icon-arrow_lift
                        animation 1s moveLeft both infinite
                        @keyframes moveLeft
                            0% {
                                transform translate(0, 0) scale(1)
                                opacity 1
                            }
                            100% {
                                transform translate(-10px, 0) scale(0.9)
                                opacity 0
                            }

                &.gonext
                    right 10px
                    .icon-arrow_lift
                        transform: rotateY(180deg)
                        animation 1s moveRight both infinite
                        @keyframes moveRight
                            0% {
                                transform translate(0, 0) scale(1) rotateY(180deg)
                                opacity 1
                            }
                            100% {
                                transform translate(10px, 0) scale(0.9) rotateY(180deg)
                                opacity 0
                            }

                .icon-arrow_lift
                    display block
                    font-size 34px

            .nowpage
                position absolute
                right 10px
                background-color rgba(0, 0, 0, 0.5)
                padding 5px 10px 5px 8px
                color #fff
                font-style italic
                font-size 12px
                border-radius 4px
                z-index 92

                .now
                    font-size 20px
                    font-weight 700
                    color #ffc107

        .close
            font-size 26px
            color #fff
            position absolute
            bottom 5vh
            width 100%
            z-index 91
            text-align center

        .bigbox
            width 100%
            overflow hidden
            transform translate(0, 0) scale(1)

            .biglist
                white-space nowrap

                .big-item
                    display inline-block

            .bigImg
                width 100%

</style>
