<template>
    <!--  需要解决-->
    <div id="app">
        <v-header :seller="seller"></v-header>
        <!--
        vue路由 https://jsfiddle.net/yyx990803/xgrjzsup/  https://router.vuejs.org/zh/api/#router-view
        在router/router.js文件中配置router的各种path配置
        -->
        <div class="tab border-1px" @click.stop.prevent="moveActiveLine" id="tab">
            <div class="tab-item">
                <router-link to="/goods">商品</router-link>
            </div>
            <div class="tab-item">
                <router-link to="/ratings">评论</router-link>
            </div>
            <div class="tab-item">
                <router-link to="/seller">商家</router-link>
            </div>
            <div class="tab-line">
                <!--
                这里注意！需要用v-bind:style=“拼接样式的字符串，
                不能{{与小程序的不同！特别注意}} vue中绑定值是直接引用变量无需加括号！”
                https://blog.csdn.net/xukongjing1/article/details/81584281
                -->
                <div class="line" :style="`transform: translate(${targetLeft}px, 0)`"></div>
            </div>
        </div>
        <!--   渲染整个前端路由不加路由不会生效,注意 这里router-view指的是goods等组件的显示,keep-alive保证变化数据的保存，否则在goods组件中选择的商品切换后会清空   -->
        <keep-alive>
            <router-view :seller="seller"></router-view>
        </keep-alive>
    </div>
</template>

<script type="text/ecmascript-6">
    import VHeader from './components/v-header/v-header';
    import { getQueryStringArgs } from 'common/js/getQueryUrl.js'

    const ERR_OK = 0;
    const debug = process.env.NODE_ENV !== 'production';
    export default {
        name: 'app',
        data() {
            return {
                seller: {
                    // 在seller属性中定义一个id属性,id使用自执行函数从url中获取
                    id: (function () {
                        let queryParam = getQueryStringArgs();
                        return queryParam.id;
                    })()
                },
                // 像显隐状态的要在data中定义，类似于header组件中的classMap是直接在create周期创建的所以不用定义！
                targetLeft: 0
            }
        },
        created() {
            const url = debug ? '/api/seller' : 'http://634174214.gitee.io/myself-vue-elme/seller.json';
            // 这是vue-resource的方法
            this.$http.get(url + '?id=' + this.seller.id).then((res) => {
                res = res.body;
                // console.log(res.data)
                if (res.errno === ERR_OK) {
                    // vue推荐方法，将两个属性进行合并，最终赋值给this.seller
                    this.seller = Object.assign({}, this.seller, res.data);
                    /*这个是仅仅进行了赋值，但是实际项目中有id存在，所以必须要将设置的Id属性与请求到的数据合并
                    * this.seller = res.data;
                    * */
                }
                // console.log('ddd', this.seller);
            });
        },
        mounted() {
            // 开始初始化时，检测active距离左侧的值，并移动跟随线，考虑如何使用计算属性制作
            this.$nextTick(() => {
                let tab = document.querySelector('#tab');
                let active = tab.querySelector('.active');
                let activeX = active.offsetLeft;
                // console.log(activeX);
                this.targetLeft = activeX;
            });
        },
        methods: {
            // 配合css制作下划线动画
            moveActiveLine: function (event) {
                // 获得点击的元素
                let clickTarget = event.target;
                // 获取点击元素距离屏幕左边距离，更改data中的值
                this.targetLeft = clickTarget.offsetLeft;
                // console.log(this.targetLeft)
            }
        },
        components: {
            VHeader
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
    @import "common/stylus/mixin.styl"
    @import "common/stylus/variable.styl"
    .tab
        width 100%
        height 40px
        display flex
        background-color #fff
        border-1px($color-col-line)

        .tab-item
            flex 1
            height 40px
            line-height 40px
            text-align center

            & > a
                display block
                width 100%
                font-size 14px

                &.active
                    color $tab-active-color

        .tab-line
            width 100%
            position absolute
            height 2px
            left 0
            bottom 0
            right 0

            .line
                width calc(100% / 3)
                height 2px
                background-color $tab-active-color
                transition all 0.5s
</style>
