<template>
    <!--
    思路：将分数转化为要遍历的数组，如4.2=【on,on,on,on,off】,满0.5就是half，然后将遍历的项作为参数传入class中
    -->
    <div class="star" :class="starCls">
        <span class="star-item"
              v-for="(item, index) in starScoreCls"
              :key="index"
              :class="item"
        ></span>
    </div>
</template>

<script type="text/ecmascript-6">
    const CLS_ON = 'on';
    const CLS_OFF = 'off';
    const CLS_HALF = 'half';
    const MAXLENGTH = 5;
    export default {
        name: 'star',
        props: {
            size: {
                type: Number,
                default: 36
            },
            score: {
                type: Number,
                default: 3
            }
        },
        computed: {
            starCls: function () {
                return `star-${this.size}`
            },
            starScoreCls: function () {
                let ret = [];
                let int = Math.floor(this.score) ;
                // 求小数值必须注意！JS计算4.1-4的时候结果不是0.1而是0.900000998，所以为了保证计算准确，这里要给小数*10计算得到整数后再/10
                let decimal = (this.score * 10 - int * 10) / 10 ;
                for (let i = 0; i < int; i++) {
                    ret.push(CLS_ON);
                }
                // 如果小数比0.5大就添加一个half
                if (decimal > 0.5) {
                    ret.push(CLS_HALF);
                }
                // 只要ret数组长度小于星星最大数量，就添加off
                while (ret.length < MAXLENGTH) {
                    ret.push(CLS_OFF)
                }
                return ret;
            }
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
    @import "../../common/stylus/mixin.styl"
    .star
        display flex
        width 100%
        align-items center

        .star-item
            background-repeat no-repeat
            background-position center center

            &:last-child
                margin-right 0

        &.star-48
            .star-item
                width 24px
                height 24px
                background-size auto 20px
                margin-right 15px

                &.on
                    bg-image('star48_on')

                &.off
                    bg-image('star48_off')

                &.half
                    bg-image('star48_half')

        &.star-36
            .star-item
                width 18px
                height 18px
                background-size auto 14px
                margin-right 10px

                &.on
                    bg-image('star36_on')

                &.off
                    bg-image('star36_off')

                &.half
                    bg-image('star36_half')

        &.star-24
            .star-item
                width 12px
                height 12px
                background-size auto 10px
                margin-right 10px

                &.on
                    bg-image('star24_on')

                &.off
                    bg-image('star24_off')

                &.half
                    bg-image('star24_half')


</style>
