<template>
    <transition name="scaleIn">
        <section class="confirm" v-show="comfirmShow">
            <div class="inner">
                <h2>{{title}}</h2>
                <span class="border-1px">{{desc}}</span>
                <div class="btn-wrapper">
                    <a href="javascript:;" class="btn" @click="_cancelConfirm">取消</a>
                    <a href="javascript:;" class="btn sure" @click="pressConfirm">确定</a>
                </div>
            </div>
        </section>
    </transition>
</template>

<script type="text/ecmascript-6">
    export default {
        name: 'confirm',
        data() {
            return {
                comfirmShow: false,
                title: '标题',
                desc: '您需要支付0元'
            }
        },
        methods: {
            //  切换显示隐藏/显示的状态
            showConfirm: function (option, confirmEvent) {
                let opt = option || {
                    title: '请配置标题',
                    desc: ''
                };
                this.comfirmShow = true;
                this.title = opt.title;
                this.desc = opt.desc;
                // 对执行事件赋值，如果不传递，那么就默认打印文字
                this._confirmEvent = confirmEvent || function () {
                    console.log('无执行事件');
                };
            },
            //  取消弹窗
            _cancelConfirm: function () {
                this.comfirmShow = false;
            },
            // 定义接收执行函数的空方法
            _confirmEvent: function () {},
            // 按下确定时
            pressConfirm: function () {
                // 执行
                this._confirmEvent();
                this.comfirmShow = false;
            }
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
    @import "../../common/stylus/variable.styl"
    @import "../../common/stylus/mixin.styl"
    .confirm
        position fixed
        top 0
        left 0
        right 0
        bottom 0
        z-index 300
        background-color $color-background-s
        display flex
        align-items center
        justify-content center
        transition: all 0.4s cubic-bezier(.54, -0.37, .74, 1.14) /* 对子元素应用动画过渡 这是必须 */
        /* https://www.cnblogs.com/jr1993/p/vue.html 给子元素添加动画 */

        &.scaleIn-enter-active
            .inner
                /* transition all 0.4s cubic-bezier(.54,-0.37,.74,1.14) */
                animation: scale-in .4s both cubic-bezier(.54, -0.37, .74, 1.14)

        &.scaleIn-leave-active
            .inner
                animation: scale-in .4s reverse both cubic-bezier(.54, -0.37, .74, 1.14)

        @keyframes scale-in {
            0% {
                transform: scale(0);
            }
            50% {
                transform: scale(1.1);
            }
            100% {
                transform: scale(1);
            }
        }

        .inner
            width 80vw
            background-color #fff
            border-radius 10px
            padding-top 30px
            color #666
            overflow hidden

            h2
                font-weight 700
                text-align center
                font-size 18px

            span
                display block
                text-align center
                font-size 16px
                padding 20px 0 20px
                border-1px($color-col-line)

            .btn-wrapper
                display flex
                width 100%
                height 50px
                overflow hidden
                border-radius 0 0 10px 10px

                .btn
                    flex 1
                    display inline-block
                    height 50px
                    line-height 50px
                    text-align center

                    &.sure
                        color #fc9153
                        background-color #f9f9f9

                    &:active
                        background-color #f2f2f2
</style>
