<template>
    <div class="shopcart">
        <section class="content" @click="toggleList">
            <div class="content-left">
                <!-- 使用表达式的时候 要加{}否则用三元表达式 (totalCount>0)?'highlight': ''  -->
                <div class="pay-cart" :class="{'highlight':totalCount>0}">
                    <span class="cart-ball">
                        <i class="icon-shopping_cart"></i>
                    </span>
                    <em class="num" v-show="totalCount>0">{{totalCount}}</em>
                </div>
                <div class="pay-price" :class="{'highlight':totalPrice > 0}">￥{{totalPrice}}</div>
                <div class="pay-info">另需配送费￥{{deliveryPrice}}元</div>
            </div>
            <div class="content-right">
                <div class="pay" :class="payClass" @click.stop.prevent="comfirmShow">{{payDesc}}</div>
            </div>
        </section>
        <!--  购物车列表  -->
        <transition name="moveIn">
            <section class="shopcart-list" v-show="listShow">
                <div class="list-wrapper">
                    <div class="head">
                        购物车 <span class="empty" @click="pressEmpty">清空</span>
                    </div>
                    <div class="list" ref="cartList">
                        <ul>
                            <li class="list-item border-1px" v-for="(food, index) in selectFoods" :key="index">
                                <div class="item-left">{{food.name}}</div>
                                <div class="item-right">
                                    <span class="price">￥{{food.price}}</span>
                                    <div class="cartlistcontrol-wrapper">
                                        <!--  监听的@add="addFood"事件驱动球下落 -->
                                        <cartcontrol :food="food" @add="addFood"></cartcontrol>
                                    </div>
                                </div>
                            </li>
                        </ul>
                    </div>
                </div>
            </section>
        </transition>

        <transition name="fadeIn">
            <div class="list-mask" v-show="listShow" @click="hideCartList"></div>
        </transition>
    </div>
</template>

<script type="text/ecmascript-6">
    import cartcontrol from '../cartcontrol/cartcontrol';
    import BScroll from 'better-scroll'
    const EVENT_PAY = 'payMoney';
    const EVENT_EMPTY = 'shopcartEmpty';
    //  这里注意购物车列表点加的传递事件不能跟之前的重复！如good组件中有@add事件了，就不能重复传递！
    const EVENT_LISTADD = 'listadd';
    export default {
        name: 'shopcart',
        props: {
            minPrice: {
                type: Number,
                default: 0
            },
            deliveryPrice: {
                type: Number,
                default: 0
            },
            selectFoods: {
                type: Array,
                default() {
                    return [
                        {price: 0, count: 1},
                        {price: 0, count: 4}
                    ]
                }
            }
        },
        data() {
            return {
                // 定义购物车列表显示状态，默认不显示，并用watch监听它的状态，状态切换在methods中
                listShow: false,

            }
        },
        computed: {
            totalPrice: function () {
                let total = 0;
                this.selectFoods.forEach(function (item) {
                    total = item.price * item.count + total;
                });
                return total;
            },
            // 全部商品的数量
            totalCount: function() {
                let allCount = 0;
                this.selectFoods.forEach(function (item) {
                    allCount = allCount + item.count
                });
                return allCount
            },
            payDesc: function () {
                let desc = '';
                switch (true) {
                    case this.totalPrice === 0:
                        desc = `￥${this.minPrice}元起送`;
                        break;
                    case this.totalPrice > 0 && this.totalPrice < this.minPrice:
                        desc = `还差￥${this.minPrice - this.totalPrice}元起送`;
                        break;
                    case this.totalPrice >= this.minPrice:
                        desc = `去结算`;
                        break
                }
                return desc
            },
            payClass: function () {
                if (this.totalPrice < this.minPrice) {
                    return 'no-enough'
                } else {
                    return 'enough'
                }
            },

        },
        watch: {
            /*
            不要在计算属性中做赋值操作，尝试用 watch 来实现类似的逻辑，当需要在数据变化时执行异步或开销较大的操作时使用watch
            在data中定义listShow，并用watch监听listshow值的变化，listshow的true/false切换交给方法去处理，watch只负责监听变化及时做出判断
            https://cn.vuejs.org/v2/api/#watch
            https://cn.vuejs.org/v2/guide/computed.html
             */
            listShow: function () {
                // 如果商品总数不存在!(this.totalCount=false)
                if (!this.totalCount) {
                    this.listShow = false
                    return false;
                }
                // 当listshow = true时
                if (this.listShow) {
                    // 在$nextTick中判断是否有滚动，没有就创建/有了就刷新
                    this.$nextTick(() => {
                        if (!this.listScroll) {
                            this.listScroll = new BScroll(this.$refs.cartList, {
                               click: true
                            });
                        } else {
                            this.listScroll.refresh();
                        }
                    });
                }
            },
            // 监听计算属性totalCount，当总数<0时，隐藏购物车列表，这里也可以放在totalCount的计算属性中判断
            totalCount: function () {
                if (this.totalCount === 0) {
                    this.hideCartList();
                }
            }
        },
        methods: {
            // 向父组件派发事件,并传递参数
            comfirmShow: function () {
                if (this.totalPrice >= this.minPrice) {
                    this.$emit(EVENT_PAY, this.totalPrice);
                }
            },
            // 点击切换显示购物车列表，这里用计算属性切换显示！！！listShow
            toggleList: function () {
                if (!this.totalCount) {
                    // 当没有商品总数时 不执行任何操作
                    return
                }
                this.listShow = !this.listShow;
            },
            // 点击list-mask背景层时隐藏
            hideCartList:function () {
                this.listShow = false;
            },
            // 清空商品数量
            emptyShopCart: function() {
                this.selectFoods.forEach((food) => {
                    food.count = 0;
                });
            },
            // 点击清空购物车按钮，向父组件good派发事件，传递执行清空函数
            pressEmpty: function () {
                this.$emit(EVENT_EMPTY, this.emptyShopCart);
            },
            /* 球下落驱动,因为下落求封装成组件了，且引用在good中，这里点击cartlist时候要向父组件发送事件，这个事件必须不能是good中监听的add，必须重新命名 */
            addFood: function (target) {
                // 不要忘记接收、并且传递参数target
                this.$emit(EVENT_LISTADD, target);
            }

        },
        components: {
            cartcontrol
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
@import "../../common/stylus/variable.styl"
@import "../../common/stylus/mixin.styl"
$shopcart-bg = #141d27
$font-color = #858585
$ball-color = rgb(0, 160, 220);
.shopcart
    width 100%
    height 50px
    position fixed
    left 0
    right 0
    bottom 0
    box-sizing border-box
    z-index 100
    .content
        display flex
        color $font-color
        background-color $shopcart-bg
        padding-left 10px
        .content-left
            flex 1 1 auto
            .pay-cart
                width 60px
                height 60px
                display inline-block
                box-sizing border-box
                background-color $shopcart-bg
                border-radius 50%
                position relative
                top -15px
                padding 5px
                &.highlight
                    color #fff
                    .cart-ball
                        background-color #00a0dc
                .cart-ball
                    background-color #2b343c
                    display block
                    border-radius 50%
                    width 50px
                    height 50px
                    line-height 63px
                    text-align center
                    .icon-shopping_cart
                        font-size 30px
                .num
                    position absolute
                    background-color #f01414
                    color #fff
                    font-size 10px
                    font-weight 700
                    top 0
                    right 0
                    padding 3px 5px 4px
                    border-radius 16px
                    text-align center
                    font-style normal
                    box-shadow 0 4px 8px 0 rgba(0,0,0,0.4)
            .pay-price
                display inline-block
                vertical-align top
                padding 0 10px
                height 50px
                line-height 50px
                &.highlight
                    color #fff
                    font-weight 700
            .pay-info
                display inline-block
                vertical-align top
                height 30px
                line-height 30px
                margin-top 10px
                border-left 1px solid #323232
                font-size 12px
                padding-left 10px
        .content-right
            flex 0 0 120px
            .pay
                width 100%
                height 50px
                text-align center
                line-height 50px
                color $font-color
                font-size 14px
                &.no-enough
                    background-color #2b333b
                &.enough
                    background-color #00b43c
                    color #fff
                    &:active
                        background-color #057c2d


    .shopcart-list
        position absolute
        top 0
        left 0
        width 100%
        z-index -1
        transform translate3d(0, -100%, 0)
        &.moveIn-enter-active, &.moveIn-leave-active
            transition all 0.4s ease-in-out
        &.moveIn-enter, &.moveIn-leave-active
            transform translate3d(0, 0%, 0)
        .list-wrapper
            background-color #fff
            .head
                height 40px
                line-height 40px
                padding-left 15px
                font-size 16px
                background-color #f2f2f2
                border-bottom 1px solid #e6e6e6
                .empty
                    position absolute
                    right 15px
                    font-size 14px
                    color #00a0dc
            .list
                padding 0 15px 0px 15px
                max-height 200px
                overflow hidden
                .list-item
                    display flex
                    justify-content space-between
                    flex-wrap nowrap
                    height 52px
                    line-height 52px
                    font-size 14px
                    border-1px(#ccc)
                    .item-left
                        flex 1
                        overflow hidden
                        white-space: nowrap
                        text-overflow:ellipsis
                        padding-right 10px
                    .item-right
                        display block
                        .price
                            display inline-block
                            color $color-red
                            vertical-align: top
                            margin-right 10px
                        .cartlistcontrol-wrapper
                            display inline-block
                            .cart-control span
                                padding 0
                            .cart-count
                                width 20px
    .list-mask
        position fixed
        width 100%
        height 100%
        top 0
        bottom 0
        left 0
        backdrop-filter blur(10px)
        z-index -2
        background-color $color-background-s
        opacity 1
        &.fadeIn-enter-active, &.fadeIn-leave-active
            transition all 0.4s ease-in-out
        &.fadeIn-enter, &.fadeIn-leave-active
            opacity 0

</style>
