<template>
    <div class="rating-select">
        <div class="select-tab">
            <span class="normal" :class="{'active':selectType === 2}" @click="select(2, $event)">
                {{desc.all}}<em class="count">{{ratings.length}}</em>
            </span>
            <span class="normal" :class="{'active':selectType === 0}" @click="select(0, $event)">
                {{desc.positive}}<em class="count">{{positive.length}}</em>
            </span>
            <span class="bad" :class="{'active':selectType === 1}" @click="select(1, $event)">
                {{desc.negative}}<em class="count">{{negative.length}}</em>
            </span>
        </div>
        <div class="only-content" :class="{'active': onlyContent}" @click="toggleContent">
            <i class="icon icon-check_circle"></i>
            <em class="desc">只显示有内容的评价</em>
        </div>
    </div>
</template>

<script type="text/ecmascript-6">
    const ALL = 2;
    const POSITIVE = 0;
    const NEGATIVE = 1;
    const EVENT_SELECT = 'select';
    const EVENT_TOGGLE = 'toggle';
    export default {
        name: 'rating-select',
        props: {
            desc: {
                type: Object,
                default() {
                    return{
                        all: '全部',
                        positive: '推荐',
                        negative: '差评'
                    }
                }
            },
            selectType: {
                type: Number,
                default: ALL
            },
            onlyContent: {
                type: Boolean,
                default: false
            },
            ratings: {
                type: Array,
                default() {
                    return [];
                }
            }
        },
        data() {
            return {

            }
        },
        computed: {
            positive: function () {
                let resultP = this.ratings.filter((item) => {
                    return item.rateType === POSITIVE
                });
                return resultP;
            },
            negative:function () {
                let resultN = this.ratings.filter((item) => {
                    return item.rateType === NEGATIVE
                });
                return resultN;
            }
        },
        methods: {
            select: function (type, event) {
                if (!event._constructed) {
                    return
                }
                this.$emit(EVENT_SELECT, type)
            },
            toggleContent: function (event) {
                if (!event._constructed) {
                    return
                }
                this.$emit(EVENT_TOGGLE)
            }
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus" scoped>
    @import '../../common/stylus/mixin.styl'
    $select-normal = rgba(0,160,220,.2)
    $select-normal-active = #00a0dc
    $select-bad = #ccc
    $select-bad-active = #666
    .rating-select
        .select-tab
            width 100%
            span
                display inline-block
                height 36px
                line-height 36px
                font-size 14px
                padding 0 15px
                margin-right 10px
                color #4d4d4d
                .count
                    font-style normal
                    padding-left 2px
            .normal
                background-color rgba(0,160,220,.2)
                &.active
                    background-color $select-normal-active
                    color #fff
            .bad
                background-color $select-bad
                &.active
                    background-color $select-bad-active
                    color #fff
        .only-content
            margin-top 20px
            padding-bottom 15px
            &.active
                .icon
                    color #00b43c
            .icon
                display inline-block
                font-size 24px
                color #999
            .desc
                display inline-block
                vertical-align top
                margin-left 5px
                font-style normal
                line-height 24px
                color #666
                font-size 14px

</style>
