<template>
    <div class="goods">
        <section class="menu-wrapper" ref="menuWrapper">
            <ul class="menu-list">
                <li
                        v-for="(good,index) in goods"
                        :key="index"
                        class="good-item border-1px"
                        :class="{'active': currentIndex === index}"
                        @click="selectMenu(index,$event)"
                        ref="menuList"
                >
                    <div class="titlebox">
                        <i v-if="good.type>0" class="icon" :class="classMap[good.type]"></i>
                        <span class="text">{{good.name}}</span>
                        <!--  这里使用计算属性，返回所有good大类下的所有商品总数，然后利用遍历的index一一对应显示  -->
                        <transition name="countScaleIn">
                            <em class="count" v-show="goodItemCount[index]>0">{{goodItemCount[index]}}</em>
                        </transition>
                    </div>
                </li>
            </ul>
        </section>
        <section class="foods-wrapper" ref="foodWrapper">
            <ul class="foods-list">
                <li
                        v-for="(good,index) in goods"
                        :key="index"
                        class="food-list"
                        ref="foodList"
                >
                    <div class="name">{{good.name}}</div>
                    <ul class="food-box">
                        <!--  选中的商品信息通过函数传递出去，注意点击的event需要在函数中作为参数传递  -->
                        <li
                                class="food-item"
                                v-for="(food,index) in good.foods"
                                :key="index"
                                @click="selectFood(food, $event)"
                        >
                            <img :src="food.icon" width="60" height="60" class="image">
                            <div class="food-info">
                                <h2 class="title">{{food.name}}</h2>
                                <span class="info">{{food.description}}</span>
                                <span class="info">
                                    <em>月售{{food.sellCount}}份</em>
                                    好评率{{food.rating}}%
                                </span>
                                <cite class="price">
                                    ￥{{food.price}}
                                    <em class="oldprice" v-show="food.oldPrice">￥{{food.oldPrice}}</em>
                                </cite>
                            </div>
                            <div class="cartcontrol-wrapper">
                                <!-- cartcontrol传递的事件叫add  -->
                                <cartcontrol :food="food" @add="addFood"></cartcontrol>
                            </div>
                        </li>
                    </ul>
                </li>
            </ul>
        </section>
        <!-- @payMoney="payMoney" 接收子组件传递过来的payMoney事件，并执行父组件中的函数  -->
        <!-- @shopcartEmpty="shopcartEmpty" 接收子组件传递过来的shopcartEmpty事件，并执行父组件中的shopcartEmpty函数  -->
        <!-- listadd点击时候传递过来的下落的小球       -->
        <shopcart
                :minPrice="seller.minPrice"
                :deliveryPrice="seller.deliveryPrice"
                :selectFoods="selectFoods"
                @payMoney="payMoney"
                @shopcartEmpty="shopcartEmpty"
                @listadd="addFood"
                ref="shopcart"
        ></shopcart>
        <!--  将下落小球从shopcart中抽离 单独做组件 -->
        <dropballs ref="dropballs"></dropballs>
        <food :food="selectedFood" @foodadd="addFood" ref="food"></food>
        <confirm ref="confirmAlert"></confirm>
    </div>
</template>

<script type="text/ecmascript-6">
    // 待优化标题栏固定 以及 menu点击取消焦点移动效果
    import shopcart from 'components/shopcart/shopcart';
    import cartcontrol from "../cartcontrol/cartcontrol";
    import confirm from "../confirm/confirm";
    import dropballs from "../dropballs/dropballs";
    import food from "../food/food";
    import BScroll from 'better-scroll';
    // 用来筛选判断数据json获取来源防止浏览器报错
    const debug = process.env.NODE_ENV !== 'production';
    const ERR_OK = 0;
    export default {
        name: 'goods',
        // 接收app.vue路由中传递来的数据
        props: {
            seller: {
                type: Object
            }
        },
        data() {
            return {
                goods: [],
                scrollY: 0,
                listHeight: [],
                // 被选中的商品对象
                selectedFood: {}
            }
        },
        created() {
            this.classMap = ['decrease', 'discount', 'special', 'invoice', 'guarantee'];
            const url = debug ? '/api/goods' : 'http://634174214.gitee.io/myself-vue-elme/goods.json';
            // 在组件创建时get数据
            this.$http.get(url).then((res) => {
                res = res.body;
                // console.log(res);
                if (res.errno === ERR_OK) {
                    this.goods = res.data;
                    // 初始化bscroll注意 这里要在获取数据的回调中进行，否则就要给$nextTick加延迟执行！https://blog.csdn.net/qq_38262910/article/details/85296932
                    this.$nextTick(() => {
                       this._initScroll();
                        // 因为 ref 本身是作为渲染结果被创建的，在初始渲染的时候你不能访问它们 - 它们还不存在，所以如果使用$refs.foodList,要么在$nextTick中使用setTimeout，要么就获取外层在使用getEByClassName
                       this._calculateHeight();
                    });
                }
            });
        },
        /*
        mounted() {
            // handleScroll为页面滚动的监听回调
            window.addEventListener('scroll', this.handleScroll);
        },
        destroyed(){
            window.removeEventListener('scroll', this.handleScroll);
        },
        */
        computed: {
            // 负责滚动foodWrapper左侧menu变化焦点
            currentIndex: function () {
                for (let i = 0;i < this.listHeight.length; i++) {
                    let height1 = this.listHeight[i];
                    let height2 = this.listHeight[i + 1];
                    // 判断是否在高度区间内，在就返回当前索引
                    if (!height2 || (this.scrollY >= height1 && this.scrollY < height2)) {
                        this._menuFollowScroll(i);
                        // console.log(i)
                        return i;
                    }
                }
                return 0;
            },
            // 选择的商品总数组
            selectFoods: function () {
                let foodArr = [];
                this.goods.forEach(function (good) {
                    good.foods.forEach(function (food) {
                        if (food.count) {
                            foodArr.push(food)
                        }
                    });
                });
                return foodArr
            },
            // 分类商品计数，使用计算属性
            goodItemCount: function () {
                let countArr = [];
                // 遍历每个good商品大类
                this.goods.forEach((good) => {
                    let goodCount = 0;
                    // 再遍历每个商品类中的商品
                    good.foods.forEach((food) => {
                        // 如果有数量属性，那么就计算他的总数
                        if (food.count) {
                            goodCount = goodCount + food.count;
                        }
                    });
                    // 将计算的总数添加进数组中，没有数量的就添加0，注意这里不能放在food循环中，是循环的good！要切记
                    countArr.push(goodCount);
                });
                // console.log(countArr)
                return countArr;
            }
        },
        methods: {
            // 初始化滚动以及实时计算滚动位置
            _initScroll: function () {
                this.foodScroll = new BScroll(this.$refs.foodWrapper, {
                    // BS会屏蔽点击事件，所以要先解开
                    click: true,
                    //不设置打印不出滚动的数值
                    probeType: 3
                });
                this.menuScroll = new BScroll(this.$refs.menuWrapper, {
                    click: true
                });
                /*
                * 每次滚动时将当前滚动的下拉数值存到scrollY中,特别注意！这里要用es6写法 使用ES5 fun(pos) {会报错！因为this.scrollY 的this指的是this.foodScroll.on这个方法的
                但是这个里面是没有scrollY 这个属性，当使用es5写法时，计算属性不会根据这里的改变而改变}
                https://segmentfault.com/q/1010000008814812?_ea=1747877
                * */
                this.foodScroll.on('scroll', (pos) => {
                    this.scrollY = Math.abs(Math.round(pos.y));
                    // console.log(this.scrollY);
                })
            },
            // 计算food滚动中的每一个foodList的高度
            _calculateHeight: function () {
                // 获取每个foodList的元素
                let foodList = this.$refs.foodList;
                // 设定在初始位置的高度
                let height = 0;
                this.listHeight.push(height);
                // console.log(foodList.length)
                for (let i = 0; i < foodList.length; i++) {
                    height = height + foodList[i].clientHeight;
                    // 当左边选择精选套餐时，currentIndex会与index差1，经过测试发现bs滚动到精选套餐时是1762，而实际高度是1763px,所以才会造成这个问题，这里第一个元素不是0，是第一个foodlist的高度！需要注意
                    // if (i === 4) {
                    //     console.log(height)
                    //     height = height - 1;
                    // }
                    this.listHeight.push(height);
                }
                // console.log(this.listHeight)
            },
            // 当foodWrapper滚动时，menuWrapper焦点超出时，menuWrapper自动滚动
            _menuFollowScroll: function (index) {
                let menuList = this.$refs.menuList;
                let el = menuList[index];
                // 滚动到元素，scrollToElement(el, time, offsetX, offsetY, easing)Y轴方向偏移100像素优化menu滚动体验
                this.menuScroll.scrollToElement(el, 300, 0 -100);
            },
            // 点击menuWrapper导致foodWrapper滚动
            selectMenu: function (index, event) {
                // 排除pc上的点击事件
                if (!event._constructed) { return }
                // 选择DOM元素
                let foodList = this.$refs.foodList;
                let el = foodList[index];
                /* scrollToElement(el, time, offsetX, offsetY, easing)
                * el 滚动到的目标元素
                * time 滚动动画执行的时长（单位 ms）
                * offsetX 相对于目标元素的横轴偏移量，如果设置为 true，则滚到目标元素的中心位置
                * offsetY 相对于目标元素的纵轴偏移量，如果设置为 true，则滚到目标元素的中心位置,这里纵向向下偏移1px与listHeight中的对应高度相等
                * easing 缓动函数，一般不建议修改
                * http://ustbhuangyi.github.io/better-scroll/doc/api.html#scrollbyx-y-time-easing
                * */
                this.foodScroll.scrollToElement(el, 300, 0, 1);
                /*
                * 这里使用滚动到元素有bug，当点击精选套餐时，会滚动到-1762px位置，但是实际上高度对应的是1763，所以导致currentIndex
                * 判断不正确，在精选套餐位置比index少1，所以这里改用scrollTo滚动到listHeight中每一块高度位置，
                * 或者修改scrollToElement，提供纵向偏移位置的参数 如上
                * 或者在高度获取阶段判断到精选套餐所在的索引，对其高度-1
                * 点击选项卡做法：data中定义cur，在结构上 :class=“{‘active': cur === index}”, 点击事件中: this.cur = index 将index传入函数
                * */
                // this.foodScroll.scrollTo(0, -this.listHeight[index], 300);
            },
            // 在父组件中接收子组件派发的事件
            addFood: function (target) {
                // 向函数中传入参数
                this._drop(target);
            },
            _drop: function(target) {
                this.$nextTick(() => {
                    // 执行子组件方法,传递进参数
                    this.$refs.dropballs.drop(target);
                });
            },
            //父组件调用子组件confirm中的方法,提交付款订单
            payMoney: function (totalPrice) {
                // 使用this.$refs获取组件
                this.$refs.confirmAlert.showConfirm({
                    title: '支付',
                    desc: `您需要支付${totalPrice}元`
                });
            },
            // 清空购物车出现提示,向confirm组件传递标题、以及确认执行的事件
            shopcartEmpty: function (fn_cartEmpty) {
                // console.log('子组件shopcart传递来的事件' + fn_cartEmpty)
                this.$refs.confirmAlert.showConfirm({
                    title: '清空购物车？',
                    desc: ''
                }, fn_cartEmpty);
            },
            // 点击出现food详细页
            selectFood: function (food, event) {
                // bs排除pc双击
                if (!event._constructed) {
                    return;
                }
                this.selectedFood = food;
                this.$refs.food.show();
            }
        },
        components: {
            shopcart,
            cartcontrol,
            confirm,
            dropballs,
            food
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
    @import "../../common/stylus/variable.styl"
    @import "../../common/stylus/mixin.styl"
    .goods
        width 100%
        position absolute
        top 179px
        bottom 50px
        left 0
        right 0
        display flex
        overflow hidden

        .menu-wrapper
            width 80px
            background-color #f2f2f2 /*
        flex: none | [ <'flex-grow'> <'flex-shrink'>? || <'flex-basis'> ]
        flex-grow属性定义项目的放大比例，默认为0，即如果存在剩余空间，也不放大,如果所有项目的flex-grow属性都为1，则它们将等分剩余空间（如果有的话）。如果一个项目的flex-grow属性为2，其他项目都为1，则前者占据的剩余空间将比其他项多一倍。
        flex-shrink属性定义了项目的缩小比例，默认为1，即如果空间不足，该项目将缩小,如果一个项目的flex-shrink属性为0，其他项目都为1，则空间不足时，前者不缩小
        flex-basis属性定义了在分配多余空间之前，项目占据的主轴空间（main size）。浏览器根据这个属性，计算主轴是否有多余空间。它的默认值为auto，即项目的本来大小。它可以设为跟width或height属性一样的值（比如350px），则项目将占据固定空间。
        */
            flex 0 0 80px

            .menu-list
                width 100%

                .good-item
                    padding 20px 10px
                    font-size 14px
                    line-height 16px
                    border-1px($color-col-line)
                    position relative
                    &.active
                        background-color #fff
                    .titlebox
                        position relative
                        display inline-block
                        padding 0px 0
                        .icon
                            display inline-block
                            width 14px
                            height 14px
                            background-size auto 14px
                            vertical-align top
                            margin-right 4px

                            &.decrease
                                bg-image('decrease_3')

                            &.discount
                                bg-image('discount_3')

                            &.special
                                bg-image('special_3')

                            &.invoice
                                bg-image('invoice_3')

                            &.guarantee
                                bg-image('guarantee_3')
                        .text
                            font-style normal
                        .count
                            position absolute
                            font-style normal
                            display block
                            width 15px
                            height 15px
                            line-height 15px
                            background-color #f01414
                            color #fff
                            font-size 10px
                            right -6px
                            top -10px
                            border-radius 50%
                            text-align center
                            transform scale(1, 1)
                            &.countScaleIn-enter-active, &.countScaleIn-leave-active
                                transition all 0.2s linear
                            &.countScaleIn-enter, &.countScaleIn-leave-active
                                transform scale(0, 0)

        .foods-wrapper
            flex 1 1 auto
            overflow hidden

            .foods-list
                width 100%

                .food-list
                    width 100%

                    .name
                        background-color #f2f2f2
                        border-left 6px solid #ccc
                        box-sizing border-box
                        padding-left 10px
                        height 30px
                        line-height 30px
                        font-size 12px

                    .food-box
                        box-sizing border-box
                        display block
                        width 100%

                        .food-item
                            display flex
                            position relative
                            padding 15px 10px 15px 15px
                            .cartcontrol-wrapper
                                position absolute
                                bottom 9px
                                right 10px


                            .image
                                flex 0 0 60px

                            .food-info
                                flex 1 1 auto
                                padding-left 10px
                                font-size 14px

                                .title
                                    width 100%
                                    margin-bottom 5px

                                .info
                                    display block
                                    color #7e8c8d
                                    font-style normal
                                    font-size 10px
                                    line-height 18px

                                    em
                                        font-style normal
                                        padding-right 5px

                                .price
                                    display block
                                    line-height 22px
                                    font-style normal
                                    font-size 14px
                                    color $tab-active-color

                                    em
                                        font-size 10px
                                        color #7e8c8d
                                        font-style normal
                                        text-decoration: line-through

</style>
