<template>
    <section class="dropBall">
        <div class="balls-wrapper" v-for="(ball, index) in balls" :key="index">
            <transition
                    name="drop"
                    v-on:before-enter="beforeDrop"
                    @enter="dropping"
                    @after-enter="afterDrop"
            >
                <div class="ball" v-show="ball.show">
                    <div class="inner inner-hook"></div>
                </div>
            </transition>
        </div>
    </section>
</template>

<script type="text/ecmascript-6">
    export default {
        name: 'dropballs',
        data() {
            return {
                balls: [
                    {
                        show: false
                    },
                    {
                        show: false
                    },
                    {
                        show: false
                    },
                    {
                        show: false
                    },
                    {
                        show: false
                    }
                ],
                dropBalls: []
            }
        },
        methods: {
            // 执行点击 加号 触发组件的事件
            drop: function (target) {
                for (let i = 0; i < this.balls.length; i++) {
                    let ball = this.balls[i];
                    // 遍历所有小球，当这个球的show为false时，取出一个不显示的小球,设置为显示true
                    if (!ball.show) {
                        ball.show = true;
                        // 设置第一个被发现的为false的小球 并将当前点击的对象（即加号）存入到对象ball中！重要
                        ball.target = target;
                        // 将小球加入下落的小球数组中
                        this.dropBalls.push(ball);
                        // return作用用来当找到第一个为false的小球的时候就终止循环
                        return;
                    }
                }
            },
            // beforeEnter-在enter之前 将动画小球移动到点击的加号的位置
            beforeDrop: function (el) {
                // console.log(this.balls);
                // 获取下落的球数组的最后一个，因为小球总是从数组末尾添加，所以获取最后一个下落的小球
                let ball = this.dropBalls[this.dropBalls.length - 1];
                // 获取加号！相对于屏幕的位置 重要！是从drop事件中传递过来的
                let rect = ball.target.getBoundingClientRect();
                let x = rect.left - 32;
                // 注意纵轴坐标是上位+ 下为 -
                let y = -(window.innerHeight - rect.top - 28);
                // 手动让动画小球元素显示
                el.style.display = 'block';
                el.style.webkitTransform = `translate3d(0, ${y}px, 0)`;
                // 元素在垂直方向运动
                el.style.transform = `translate3d(0, ${y}px, 0)`;
                // 内层元素在水平方向运动
                let inner = el.getElementsByClassName('inner-hook')[0];
                inner.style.transform = `translate3d(${x}px, 0, 0)`;
                inner.style.webkitTransform = `translate3d(${x}px, 0, 0)`;
            },
            // enter-动画进入时，设置动画xy轴终点位置为translate3d(0, 0, 0)，注意浏览器重绘
            dropping: function (el, done) {
                // 触发浏览器重绘 执行动画，否则transfrom会不生效直接到动画末尾状态
                /* eslint-disable no-unused-vars */
                this._reflow = document.body.offsetHeight;
                el.style.webkitTransform = `translate3d(0, 0, 0)`;
                el.style.transform = `translate3d(0, 0, 0)`;
                let inner = el.getElementsByClassName('inner-hook')[0];
                inner.style.webkitTransform = `translate3d(0, 0, 0)`;
                inner.style.transform = `translate3d(0, 0, 0)`;
                // 动画完成执行回调函数，执行下一个钩子函数，注意这里事件结束的写法是都小写
                el.addEventListener('transitionend', done);
            },
            // afterEnter-enter结束后，回收小球，按照先入先出原则，删除dropBalls数组第一个小球，并重置balls中对应小球的状态，回收到balls中
            afterDrop: function (el) {
                // 取得数组中第一个元素，并删除它，并返回删除的元素
                let ball = this.dropBalls.shift();
                // 如果球是显示的 就隐藏
                if (ball.show) {
                    ball.show = false;
                    el.style.display = 'none';
                }
            }
        }
    }
</script>

<style lang="stylus" rel="stylesheet/stylus">
    $ball-color = rgb(0, 160, 220)
    .dropBall
        position fixed
        left 32px
        bottom 28px
        z-index 101
        width 16px
        height 16px
        .ball
            position absolute
            left 0
            top 0
            /* http://yisibl.github.io/cubic-bezier/#.02,-0.25,1,-0.25 贝塞尔曲线直接拖拽出抛物线并给y轴赋值css动画样式 就在y轴有了抛物线效果 */
            transition all 0.4s cubic-bezier(0.49, -0.29, 0.75, 0.41)
            .inner
                width 16px
                height 16px
                border-radius 50%
                transition all 0.4s linear
                background-color $ball-color


</style>
